pub fn is_float_type_node(n: Rc<Node>) -> bool {
    {
        let normed = normalize_access_type_node(n.clone());
((normed.name.clone() == "Float".to_string()) && node_is_leaf(normed.clone()))
}
}

pub fn infer_literal_node(lit: Rc<LiteralValue>) -> Rc<Node> {
    match (*lit.clone()).clone() {
    LiteralValue::LitStr { .. } => leaf_node("String".to_string()),
    LiteralValue::LitInt { .. } => leaf_node("Int".to_string()),
    LiteralValue::LitFloat { .. } => leaf_node("Float".to_string()),
    LiteralValue::LitBool { .. } => leaf_node("Bool".to_string()),
    LiteralValue::LitNull => with_optional_cardinality(leaf_node("Unit".to_string())),
}
}

pub fn method_receiver_element_node(receiver_type: Rc<Node>) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(receiver_type.clone());
if ((node_has_structure(normed.clone()) == false) && ((normed.children.clone().len() as i64) == 1)) {
            match normed.children.clone().first().cloned() {
    Some(el) => el.clone(),
    None => receiver_type.clone(),
}
} else {
            if node_is_map(normed.clone()) {
                match normed.children.clone().iter().cloned().skip(1 as usize).collect::<Vec<_>>().first().cloned() {
    Some(val_type) => val_type.clone(),
    None => receiver_type.clone(),
}
} else {
                receiver_type.clone()
}
}
}
}

pub fn extract_optional_inner_node(n: Rc<Node>) -> Rc<Node> {
    if node_is_optional(n.clone()) {
        with_required_cardinality(n.clone())
} else {
        n.clone()
}
}

pub fn infer_binop_type_node(op: BinOpKind, left_type: Rc<Node>) -> Rc<Node> {
    match op.clone() {
    BinOpKind::BinEq => leaf_node("Bool".to_string()),
    BinOpKind::BinNe => leaf_node("Bool".to_string()),
    BinOpKind::BinLt => leaf_node("Bool".to_string()),
    BinOpKind::BinGt => leaf_node("Bool".to_string()),
    BinOpKind::BinLe => leaf_node("Bool".to_string()),
    BinOpKind::BinGe => leaf_node("Bool".to_string()),
    BinOpKind::BinAnd => leaf_node("Bool".to_string()),
    BinOpKind::BinOr => leaf_node("Bool".to_string()),
    BinOpKind::NullCoalesce => extract_optional_inner_node(left_type.clone()),
    _ => left_type.clone(),
}
}

pub fn for_each_element_type_node(n: Rc<Node>) -> Rc<Node> {
    {
        let normed = normalize_access_type_node(n.clone());
let is_single_child = ((node_has_structure(normed.clone()) == false) && ((normed.children.clone().len() as i64) == 1));
let extracted = if is_single_child.clone() {
            normed.children.clone().first().cloned()
} else {
            None
};
match extracted.clone() {
    Some(el) => el.clone(),
    None => if (node_is_leaf(normed.clone()) && (normed.name.clone() == "String".to_string())) {
            leaf_node("String".to_string())
} else {
            normed.clone()
},
}
}
}

pub fn emit_map_has(m: HashMap<String, bool>, key: String) -> bool {
    match v2_rt::map_get(&m, key.clone()) {
    Some(_) => true,
    None => false,
}
}
